#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
const float upperC = 8.0f;
const float lowerC = 4.0f;
bool cooling = false;
bool previousOpen = false;
bool alarmActive = false;
bool firstDisplay = true;
unsigned long openedAt = 0;
unsigned long lastReport = 0;
unsigned long lastDisplay = 0;

void setup() {
  pinMode(A1, INPUT);
  pinMode(2, INPUT_PULLUP);
  pinMode(10, OUTPUT);
  pinMode(6, OUTPUT);
  pinMode(13, OUTPUT);
  digitalWrite(10, LOW);
  digitalWrite(13, LOW);
  noTone(6);
  Serial.begin(9600);
  display.setBrightness(5);
  display.clear();
}

void loop() {
  unsigned long now = millis();
  float temperature = analogRead(A1) * (500.0f / 1023.0f);
  bool doorOpen = digitalRead(2) == HIGH;
  if (doorOpen && !previousOpen) openedAt = now;
  previousOpen = doorOpen;
  unsigned long duration = doorOpen ? now - openedAt : 0;

  if (temperature > upperC) cooling = true;
  else if (temperature < lowerC) cooling = false;
  digitalWrite(10, cooling ? HIGH : LOW);

  bool alarm = doorOpen && duration > 10000UL;
  if (alarm != alarmActive) {
    if (alarm) tone(6, 2000);
    else noTone(6);
    alarmActive = alarm;
  }
  digitalWrite(13, alarm && ((duration / 500UL) % 2UL) ? HIGH : LOW);

  if (doorOpen && temperature > upperC && now - lastReport >= 1000UL) {
    Serial.println("critical cooling loss");
    lastReport = now;
  }

  if (firstDisplay || now - lastDisplay >= 200UL) {
    firstDisplay = false;
    lastDisplay = now;
    if ((now / 1000UL) % 2UL == 0) {
      display.showNumberDec((int)(temperature + 0.5f), false);
    } else {
      unsigned long seconds = duration / 1000UL;
      if (seconds > 9999UL) seconds = 9999UL;
      display.showNumberDec((int)seconds, false);
    }
  }
}
